    }

    static long computeBase(long n) {
        int digits = getDigitCount(n);
        long base = 0, power = 1;
        for (int i = 0; i < digits; i++) {
            base += power;
            power *= 10;
        }
        if (base <= n) return base;
        return (base - 1) / 10;
    }

    static long solveNumber(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base_value = computeBase(n);
        long boundary = base_value * 10 + 1;
        if (n % base_value == 0) {
            long quotient = n / base_value;
            if (n <= boundary / 2 + base_value) return getDigitCount(base_value) * quotient;
            else {
                long diff = solveNumber(boundary - n);
                return getDigitCount(boundary) + diff;
            }
        } else {
            long lower = (n / base_value) * base_value;
            long upper = (n / base_value + 1) * base_value;
            long total_res = solveNumber(lower) + solveNumber(n - lower);
            if (n > boundary / 2) {
                total_res = Math.min(solveNumber(lower) + solveNumber(n - lower),
                        getDigitCount(boundary) + solveNumber(boundary - n));
            }
            return total_res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(solveNumber(n));
